<?php $pageTitle='Inventory'; require '../includes/functions.php'; require_admin(); if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$_POST['movement_type']=='Stock In'?$_POST['quantity']:-$_POST['quantity'],$_POST['product_id']]);$pdo->prepare('INSERT INTO inventory (product_id,movement_type,quantity,remarks) VALUES (?,?,?,?)')->execute([$_POST['product_id'],$_POST['movement_type'],$_POST['quantity'],$_POST['remarks']]);redirect('inventory.php');} $products=$pdo->query('SELECT * FROM products WHERE is_archived=0')->fetchAll(); $logs=$pdo->query('SELECT i.*,p.name FROM inventory i JOIN products p ON p.id=i.product_id ORDER BY i.id DESC LIMIT 100')->fetchAll(); require '_header.php'; ?>
<h1 class="fw-bold mb-4">Inventory Management</h1><form method="post" class="bg-white p-4 rounded-4 shadow-sm row g-2 mb-4"><div class="col-md-3"><select name="product_id" class="form-select"><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?> (<?= $p['stock'] ?>)</option><?php endforeach; ?></select></div><div class="col-md-2"><select name="movement_type" class="form-select"><option>Stock In</option><option>Stock Out</option></select></div><div class="col-md-2"><input name="quantity" type="number" min="1" class="form-control" placeholder="Qty"></div><div class="col-md-3"><input name="remarks" class="form-control" placeholder="Remarks"></div><div class="col-md-2"><button class="btn btn-red w-100">Save</button></div></form><h4>Inventory Logs and Movement History</h4><table class="table bg-white"><thead><tr><th>Date</th><th>Product</th><th>Type</th><th>Qty</th><th>Remarks</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= e($l['created_at']) ?></td><td><?= e($l['name']) ?></td><td><?= e($l['movement_type']) ?></td><td><?= $l['quantity'] ?></td><td><?= e($l['remarks']) ?></td></tr><?php endforeach; ?></tbody></table><?php require '_footer.php'; ?>